/* SBA Workspace public interface, injected inside app_v2's IIFE. */
document.title='BM4 SBA Studio';
let studioRasterKey='';
function makeStudioRasterBackdrop(){
  const root=document.documentElement;
  if(!root.classList.contains('high-pixel-display')){root.style.removeProperty('--studio-ambient-raster');studioRasterKey='';return}
  const styles=getComputedStyle(root),names=['--bg','--cyan','--violet','--pink','--accent'],colours=names.map(name=>styles.getPropertyValue(name).trim()),key=colours.join('|');
  if(!colours[0]||key===studioRasterKey)return;
  const canvas=document.createElement('canvas');canvas.width=480;canvas.height=270;
  const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)return;
  ctx.fillStyle=colours[0];ctx.fillRect(0,0,canvas.width,canvas.height);
  const glow=(x,y,r,colour,alpha)=>{ctx.globalAlpha=alpha;for(const offset of [-canvas.height,0,canvas.height]){const wrappedY=y+offset,gradient=ctx.createRadialGradient(x,wrappedY,0,x,wrappedY,r);gradient.addColorStop(0,colour);gradient.addColorStop(1,'transparent');ctx.fillStyle=gradient;ctx.fillRect(0,0,canvas.width,canvas.height)}};
  glow(68,48,150,colours[1]||colours[4],.35);glow(398,54,150,colours[2]||colours[4],.31);glow(356,238,165,colours[3]||colours[4],.25);glow(92,225,125,colours[4],.22);ctx.globalAlpha=1;
  root.style.setProperty('--studio-ambient-raster',`url("${canvas.toDataURL('image/webp',.62)}")`);studioRasterKey=key;
}
function syncDisplayPerformance(){const dpr=Math.max(1,window.devicePixelRatio||1),pixelWidth=Math.max(screen.width||0,innerWidth||0)*dpr,pixelHeight=Math.max(screen.height||0,innerHeight||0)*dpr;document.documentElement.classList.add('studio-performance');document.documentElement.classList.toggle('high-pixel-display',pixelWidth>=3000||pixelHeight>=1800);if(document.body)requestAnimationFrame(makeStudioRasterBackdrop)}
syncDisplayPerformance();let displayPerformanceFrame=0;addEventListener('resize',()=>{cancelAnimationFrame(displayPerformanceFrame);displayPerformanceFrame=requestAnimationFrame(syncDisplayPerformance)},{passive:true});
const studioScrollBehavior=()=>document.documentElement.classList.contains('high-pixel-display')?'auto':'smooth';
const studioBaseSetTheme=setTheme;setTheme=function(){studioBaseSetTheme();requestAnimationFrame(makeStudioRasterBackdrop)};

