renderExam=function(){
  clearInterval(tick);tick=null;flushTime();
  const s=db.current;if(!s){view='home';return render()}
  const i=s.current,q=s.questions[i],ord=s.optionOrders[i],answered=s.answers.filter(x=>x!==null).length,feedbackMode=s.feedbackMode||(s.mode==='full'?'end':'instant'),revealNow=feedbackMode==='instant'&&s.answers[i]!==null,hasAnswer=s.answers[i]!==null,correct=hasAnswer&&s.answers[i]===q.answer;
  header(`${s.mode==='full'?'Full assessment':s.title} · ${s.bankTitle} · ${answered}/${s.questions.length} answered`,s.timed?'Remaining …':'Untimed','');
  const immediateFeedback=revealNow?`<section class="practice-feedback ${correct?'correct':'incorrect'}"><div><span class="result-label ${correct?'correct':'incorrect'}">${correct?'CORRECT':'INCORRECT'}</span><p><b>Best answer:</b> ${esc(q.options[q.answer])}</p><p>${esc(q.why)}</p></div><button class="v2-btn" data-live-deep-review="${i}">Explore further</button></section>`:'';
  document.getElementById('view').innerHTML=`<div class="exam-layout"><article class="exam-card"><div class="q-top"><b>Question ${i+1} of ${s.questions.length}</b><button class="v2-btn ${s.flags[i]?'warn':''}" data-act="flag">${s.flags[i]?'★ Flagged':'☆ Flag'}</button></div><h2>Question ${i+1}</h2><div class="question-stem" data-q-stem="${i}">${esc(q.stem)}</div>${safeImage(q)}<div class="answer-list">${ord.map((canonical,pos)=>`<div class="answer-row"><button class="answer ${s.answers[i]===canonical?'selected':''} ${s.eliminated[i][canonical]?'eliminated':''} ${revealNow&&canonical===q.answer?'practice-correct':''} ${revealNow&&canonical===s.answers[i]&&canonical!==q.answer?'practice-wrong':''}" data-act="answer" data-value="${canonical}"><b>${letters[pos]}.</b> ${esc(q.options[canonical])}</button><button class="xout ${s.eliminated[i][canonical]?'active':''}" data-act="eliminate" data-value="${canonical}" title="Rule out option ${letters[pos]}">✕</button></div>`).join('')}</div>${immediateFeedback}<div class="confidence"><b>Confidence:</b>${['Guess','Leaning unsure','Unsure','Fairly confident','Confident'].map((x,j)=>`<button class="v2-btn ${s.confidence[i]===x?'active':''}" data-act="confidence" data-value="${x}">${x}<kbd class="keycap">${['I','I+O','O','O+P','P'][j]}</kbd></button>`).join('')}</div><div class="button-row" style="justify-content:space-between"><button class="v2-btn" data-act="prev" ${i===0?'disabled':''}>← Previous <kbd class="keycap">8</kbd></button><button class="v2-btn warn" data-act="submit">Finish session</button><button class="v2-btn primary" data-act="next" ${i===s.questions.length-1?'disabled':''}><kbd class="keycap">0</kbd> Next →</button></div></article><aside class="side-card"><h3>Navigator</h3><p>${answered} of ${s.questions.length} answered</p><div class="nav-grid-v2">${s.questions.map((_,j)=>`<button class="q-dot ${s.answers[j]!==null?'answered':''} ${s.flags[j]?'flagged':''} ${j===i?'current':''} ${['Guess','Leaning unsure','Unsure'].includes(s.confidence[j])?'lowconf':''}" data-act="jump" data-value="${j}">${j+1}</button>`).join('')}</div><p class="muted"><small>Filled = answered · amber = flagged · ? = low confidence</small></p><p><small>Active time on this question: <b id="qtime">${fmtTime(s.times[i])}</b></small></p>${feedbackMode==='end'?'<p class="assessment-lock-note"><small>Answers and Deep Review stay hidden until you finish this session.</small></p>':'<p class="assessment-lock-note"><small>Correctness and Deep Review unlock after each answer.</small></p>'}</aside></div>`;
  const stemNode=document.querySelector(`[data-q-stem="${i}"]`);if(stemNode)stemNode.innerHTML=editorText(q.stem);document.querySelectorAll('.answer[data-value]').forEach(button=>{const canonical=Number(button.dataset.value),label=button.querySelector('b')?.outerHTML||'';button.innerHTML=label+' '+editorText(q.options[canonical])});const feedback=document.querySelector('.practice-feedback');if(feedback){const paragraphs=feedback.querySelectorAll('p');if(paragraphs[0])paragraphs[0].innerHTML='<b>Best answer:</b> '+editorText(q.options[q.answer]);if(paragraphs[1])paragraphs[1].innerHTML=editorText(q.why)}
  const feedbackStatus=document.querySelector('.assessment-lock-note small');if(feedbackStatus)feedbackStatus.textContent=feedbackMode==='end'?'Answers and explanations stay hidden until you finish this session.':'Correctness and explanations appear after each answer.';
  activeStamp=Date.now();runTimer();
};

const baseNormaliseBank=normaliseBank;
