function asTextArray(value){return Array.isArray(value)?value.map(x=>String(x||'').trim()).filter(Boolean):[]}
function validOptionIndexes(value,q){return[...new Set((Array.isArray(value)?value:[]).map(Number).filter(x=>Number.isInteger(x)&&x>=0&&x<q.options.length))]}
function occurrenceExists(stem,quote,occurrence){let from=0,found=-1;for(let n=0;n<occurrence;n++){found=stem.toLowerCase().indexOf(quote.toLowerCase(),from);if(found<0)return false;from=found+quote.length}return true}
const TAXONOMY_VERSION=1;
const STANDARD_TAXONOMY={
  themes:['Cardiovascular','Respiratory','Gastrointestinal','Renal','Endocrinology & Reproduction','Nutrition & Metabolism','Neurology','Musculoskeletal','Dermatology','Haematology','Infection & Immunity','Oncology','Psychiatry','Paediatrics','Emergency & Critical Care','Public Health','General'],
  subjects:['Anatomy','Physiology','Biochemistry','Pathology','Pharmacology','Clinical','Clinical Skills & Investigations','Haematology','Infection & Microbiology','Immunology','Genetics','Nutrition & Metabolism','Oncology','Psychology','Public Health & Epidemiology','Evidence based medicine & statistics','Ethics & Law','Communication & Professionalism','Radiology & Imaging','Surgery','Paediatrics','Obstetrics & Gynaecology','Other'],
  domains:['Anatomy','Physiology','Pathology','Pharmacology','Clinical','Investigation / data interpretation','Clinical numeracy','Infection & Microbiology','Immunology','Genetics','Oncology','Ethics & Law','EBM & statistics','Population science','Psychology / sociology','Other'],
  difficulties:['Easy','Moderate','Hard']
};
const TAXONOMY_ALIASES={
  themes:{cardiac:'Cardiovascular',cardiology:'Cardiovascular','cardiovascular medicine':'Cardiovascular',heart:'Cardiovascular',pulmonary:'Respiratory','respiratory medicine':'Respiratory',chest:'Respiratory',gastroenterology:'Gastrointestinal',gi:'Gastrointestinal',hepatobiliary:'Gastrointestinal',nephrology:'Renal',kidney:'Renal',urology:'Renal',endocrine:'Endocrinology & Reproduction',endocrinology:'Endocrinology & Reproduction',reproduction:'Endocrinology & Reproduction',reproductive:'Endocrinology & Reproduction',nutrition:'Nutrition & Metabolism',metabolism:'Nutrition & Metabolism',obesity:'Nutrition & Metabolism',neurology:'Neurology',neuroscience:'Neurology',orthopaedics:'Musculoskeletal',orthopedics:'Musculoskeletal',rheumatology:'Musculoskeletal',skin:'Dermatology',hematology:'Haematology',infection:'Infection & Immunity','infectious diseases':'Infection & Immunity',microbiology:'Infection & Immunity',cancer:'Oncology','emergency medicine':'Emergency & Critical Care','critical care':'Emergency & Critical Care','public health and epidemiology':'Public Health','general medicine':'General',multisystem:'General'},
  subjects:{'clinical medicine':'Clinical',clinical:'Clinical','clinical skills':'Clinical Skills & Investigations',investigations:'Clinical Skills & Investigations',hematology:'Haematology',microbiology:'Infection & Microbiology',infection:'Infection & Microbiology','infectious diseases':'Infection & Microbiology','molecular biology':'Biochemistry','biochemistry and genetics':'Biochemistry','evidence based medicine':'Evidence based medicine & statistics',ebm:'Evidence based medicine & statistics',statistics:'Evidence based medicine & statistics','public health':'Public Health & Epidemiology',epidemiology:'Public Health & Epidemiology',psychology:'Psychology',sociology:'Psychology',ethics:'Ethics & Law',law:'Ethics & Law',communication:'Communication & Professionalism',professionalism:'Communication & Professionalism',radiology:'Radiology & Imaging',imaging:'Radiology & Imaging',obstetrics:'Obstetrics & Gynaecology',gynaecology:'Obstetrics & Gynaecology',gynecology:'Obstetrics & Gynaecology'},
  domains:{'applied anatomy':'Anatomy',mechanism:'Physiology',diagnosis:'Clinical',management:'Clinical','clinical medicine':'Clinical',investigation:'Investigation / data interpretation',interpretation:'Investigation / data interpretation','data interpretation':'Investigation / data interpretation',calculation:'Clinical numeracy',numeracy:'Clinical numeracy',microbiology:'Infection & Microbiology',infection:'Infection & Microbiology',development:'Genetics',embryology:'Genetics',statistics:'EBM & statistics','evidence based medicine':'EBM & statistics',ebm:'EBM & statistics',epidemiology:'Population science','public health':'Population science',ethics:'Ethics & Law',law:'Ethics & Law',psychology:'Psychology / sociology',sociology:'Psychology / sociology'},
  difficulties:{easy:'Easy',moderate:'Moderate',medium:'Moderate',hard:'Hard',difficult:'Hard'}
};
const TAXONOMY_FALLBACKS={themes:'General',subjects:'Other',domains:'Other',difficulties:'Moderate'};
const taxonomyKey=value=>String(value||'').normalize('NFKD').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').trim();
const taxonomyMaps={};
function taxonomyMap(kind){if(taxonomyMaps[kind])return taxonomyMaps[kind];const map=new Map;STANDARD_TAXONOMY[kind].forEach(value=>map.set(taxonomyKey(value),value));Object.entries(TAXONOMY_ALIASES[kind]||{}).forEach(([alias,value])=>map.set(taxonomyKey(alias),value));return taxonomyMaps[kind]=map}
function canonicalTaxonomyValue(kind,value){return taxonomyMap(kind).get(taxonomyKey(value))||TAXONOMY_FALLBACKS[kind]}
function canonicaliseQuestionTaxonomy(q){q.theme=canonicalTaxonomyValue('themes',q.theme);q.subjects=[...new Set((Array.isArray(q.subjects)?q.subjects:[q.subjects]).filter(Boolean).map(value=>canonicalTaxonomyValue('subjects',value)))];if(!q.subjects.length)q.subjects=['Other'];q.domain=canonicalTaxonomyValue('domains',q.domain);q.difficulty=canonicalTaxonomyValue('difficulties',q.difficulty);q.taxonomyVersion=TAXONOMY_VERSION;return q}
function taxonomySchema(){return{version:TAXONOMY_VERSION,themes:[...STANDARD_TAXONOMY.themes],subjects:[...STANDARD_TAXONOMY.subjects],domains:[...STANDARD_TAXONOMY.domains],difficulties:[...STANDARD_TAXONOMY.difficulties],rule:'Use these labels exactly. The importer maps common aliases and sends unknown reporting labels to General or Other.'}}
function deriveClueQuote(q){
  const stem=String(q.stem),candidates=[q.topic,...(q.lo||[])].map(String).filter(x=>x.length>=4).sort((a,b)=>b.length-a.length);
  for(const candidate of candidates){const at=stem.toLowerCase().indexOf(candidate.toLowerCase());if(at>=0)return stem.slice(at,at+candidate.length)}
  const sourceWords=candidates.join(' ').toLowerCase().match(/[a-z][a-z-]{3,}/g)||[];
  const words=stem.match(/[A-Za-z][A-Za-z-]*/g)||[];
  const hit=words.find(w=>sourceWords.includes(w.toLowerCase()));if(hit)return hit;
  const first=(stem.split(/[.?!]/).find(x=>x.trim().split(/\s+/).length>=4)||stem).trim().split(/\s+/);
  return first.slice(Math.max(0,first.length>10?2:0),Math.min(first.length,10)).join(' ');
}
function fallbackDeepReview(q){
  const quote=deriveClueQuote(q),wrong=q.options.map((text,index)=>index===q.answer?null:{label:text,text:q.distractors[index]}).filter(Boolean);
  return{version:1,generatedFallback:true,testedConcept:q.topic||q.lo?.[0]||'Core concept',keyClues:[{id:'core-clue',quote,occurrence:1,explanation:[`This wording helps identify the question's central ${String(q.topic||'concept').toLowerCase()}.`,q.why],supports:[q.answer],arguesAgainst:[]}],keyConcept:{summary:q.why,paragraphs:[`Learning objective: ${(q.lo||['Review the tested concept']).join('; ')}`],comparisonPoints:wrong},commonTraps:wrong.slice(0,2).map(x=>x.text),recogniseNextTime:[`Identify the stem detail linked to ${q.topic||'the tested concept'}, then compare options from the same category.`],followUpQuestions:[]}
}
function normaliseDeepReview(q){
  const warnings=[],raw=q.deepReview&&typeof q.deepReview==='object'?q.deepReview:fallbackDeepReview(q),fallback=raw.generatedFallback?raw:fallbackDeepReview(q);
  const clues=(Array.isArray(raw.keyClues)?raw.keyClues:[]).slice(0,6).map((clue,index)=>{const quote=String(clue?.quote||'').trim(),occurrence=Math.max(1,Number(clue?.occurrence)||1);if(!quote||!occurrenceExists(q.stem,quote,occurrence)){warnings.push(`Clue ${index+1} does not match the stem`);return null}const supports=validOptionIndexes(clue.supports,q),arguesAgainst=validOptionIndexes(clue.arguesAgainst,q).filter(x=>!supports.includes(x));return{id:String(clue.id||`clue-${index+1}`).replace(/[^a-z0-9_-]/gi,'-'),quote,occurrence,explanation:asTextArray(clue.explanation).slice(0,5),supports,arguesAgainst}}).filter(Boolean);
  const kc=raw.keyConcept&&typeof raw.keyConcept==='object'?raw.keyConcept:fallback.keyConcept;
  const comparisons=(Array.isArray(kc.comparisonPoints)?kc.comparisonPoints:[]).slice(0,8).map(x=>({label:String(x?.label||'').trim(),text:String(x?.text||'').trim()})).filter(x=>x.label&&x.text);
  const followUps=(Array.isArray(raw.followUpQuestions)?raw.followUpQuestions:[]).slice(0,5).map(x=>({prompt:String(x?.prompt||'').trim(),answer:String(x?.answer||'').trim()})).filter(x=>x.prompt);
  const authoredReview=raw.generatedFallback===false;
  const review={version:1,generatedFallback:!!raw.generatedFallback,testedConcept:String(raw.testedConcept||q.topic||fallback.testedConcept),keyClues:clues.length?clues:(authoredReview?[]:fallback.keyClues),keyConcept:{summary:String(kc.summary||q.why),paragraphs:asTextArray(kc.paragraphs).slice(0,8),comparisonPoints:comparisons},commonTraps:asTextArray(raw.commonTraps).slice(0,6),recogniseNextTime:asTextArray(raw.recogniseNextTime).slice(0,6),followUpQuestions:followUps,sourceNotes:asTextArray(raw.sourceNotes).slice(0,6),reviewedAt:raw.reviewedAt?String(raw.reviewedAt):null,_validationWarnings:warnings};
  q.deepReview=review;return warnings;
}
normaliseBank=function(x,builtin=false){const b=baseNormaliseBank(x,builtin);b.data.questions.forEach(q=>{canonicaliseQuestionTaxonomy(q);normaliseDeepReview(q)});b.data.taxonomyVersion=TAXONOMY_VERSION;b.data.taxonomy=taxonomySchema();if(builtin){b.title='BM4 Clinical Foundations — Original Bank';b.data.title=b.title;b.data.blueprint.source='BM4 Clinical Foundations original question bank';b.data.blueprint.note='Theme and subject counts describe this question bank only; they are not an official examination blueprint.'}return b};
db.banks.forEach(b=>{b.data.questions.forEach(q=>{canonicaliseQuestionTaxonomy(q);normaliseDeepReview(q)});b.data.taxonomyVersion=TAXONOMY_VERSION;b.data.taxonomy=taxonomySchema();updateEditorBankStats?.(b);if(b.builtin){b.title='BM4 Clinical Foundations — Original Bank';b.data.title=b.title;b.data.blueprint.source='BM4 Clinical Foundations original question bank';b.data.blueprint.note='Theme and subject counts describe this question bank only; they are not an official examination blueprint.'}});[...(db.history||[]),...(db.current?[db.current]:[])].forEach(a=>a.questions?.forEach(canonicaliseQuestionTaxonomy));db.taxonomyVersion=TAXONOMY_VERSION;db.history=db.history.filter(a=>a.id!==BASELINE_SEED.id);if(db.current&&!['instant','end'].includes(db.current.feedbackMode))db.current.feedbackMode=db.current.mode==='full'?'end':'instant';db.history.forEach(a=>{if(!['instant','end'].includes(a.feedbackMode))a.feedbackMode=a.mode==='full'?'end':'instant'});save();

function deepAudit(b){const questions=b.data.questions,authored=questions.filter(q=>!q.deepReview?.generatedFallback).length,warnings=questions.reduce((n,q)=>n+(q.deepReview?._validationWarnings?.length||0),0);return{authored,fallback:questions.length-authored,warnings,total:questions.length}}
function importPreviewHtml(b){const a=deepAudit(b),difficulty=countBy(b.data.questions,q=>[q.difficulty]);return`<div class="import-summary"><div class="metric"><b>${b.data.questions.length}</b><small>Questions</small></div><div class="metric"><b>${a.authored}</b><small>Enhanced reviews</small></div><div class="metric"><b>${a.fallback}</b><small>Standard reviews</small></div><div class="metric"><b>${a.warnings}</b><small>Clue warnings</small></div></div><p><b>Difficulty:</b> Easy ${difficulty.Easy||0} · Moderate ${difficulty.Moderate||0} · Hard ${difficulty.Hard||0}</p><p><b>Reporting categories:</b> normalised to canonical taxonomy v${TAXONOMY_VERSION}. Common aliases are merged automatically.</p>${a.warnings?'<div class="insight warn"><b>Some clue highlights need attention.</b><br>The bank can still be imported. Invalid phrase anchors will use a safe feedback-derived clue instead.</div>':'<div class="insight good"><b>Validation passed.</b><br>Question structure, answers and enhanced review data are usable.</div>'}`}
importBankFile=function(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const b=normaliseBank(JSON.parse(reader.result));pendingBankImport=b;modal(`<div class="q-top"><div><span class="eyebrow">Import preview</span><h2>${esc(b.title)}</h2></div><button class="v2-btn" data-act="close-modal">Cancel</button></div>${importPreviewHtml(b)}<p class="muted">Nothing has been saved yet. Imported banks remain separate from the included BM4 bank.</p><div class="button-row end"><button class="v2-btn primary" data-studio-act="confirm-bank-import">Import this bank</button></div>`)}catch(error){alert('Import failed without changing saved data: '+error.message)}};reader.readAsText(file)};
function pastedJsonObject(raw){let text=String(raw||'').replace(/^\uFEFF/,'').trim();if(/^```/i.test(text))text=text.replace(/^```(?:json)?\s*/i,'').replace(/\s*```\s*$/,'').trim();try{return JSON.parse(text)}catch(firstError){const start=text.indexOf('{'),end=text.lastIndexOf('}');if(start>=0&&end>start){try{return JSON.parse(text.slice(start,end+1))}catch{}}throw Error('The pasted text is not valid JSON. Copy the complete object from the opening { to the closing }.')}}
function pasteBankModal(){pendingBankImport=null;modal(`<div class="q-top"><div><span class="eyebrow">Import without a file</span><h2>Paste question-bank JSON</h2></div><button class="v2-btn" data-act="close-modal">Close</button></div><p>Paste the complete JSON response from your AI. Plain JSON and fenced <code>\`\`\`json</code> blocks are both accepted.</p><label class="field paste-json-field"><span>Question-bank JSON</span><textarea id="bankJsonPaste" rows="18" spellcheck="false" placeholder='{\n  "schemaVersion": 2,\n  "title": "My question bank",\n  "questions": [ ... ]\n}'></textarea></label><div class="insight danger hidden-v2" id="pasteJsonError" role="alert"></div><p class="privacy-note"><b>Private:</b> parsing and validation happen in this browser. The text is not sent anywhere.</p><div class="button-row end"><button class="v2-btn primary" data-studio-act="preview-pasted-bank">Validate and preview</button></div>`);setTimeout(()=>document.getElementById('bankJsonPaste')?.focus(),0)}
function previewPastedBank(){const field=document.getElementById('bankJsonPaste'),error=document.getElementById('pasteJsonError');try{const b=normaliseBank(pastedJsonObject(field?.value));pendingBankImport=b;modal(`<div class="q-top"><div><span class="eyebrow">Pasted JSON preview</span><h2>${esc(b.title)}</h2></div><button class="v2-btn" data-act="close-modal">Cancel</button></div>${importPreviewHtml(b)}<p class="muted">Nothing has been saved yet. The bank will remain separate from the included BM4 bank.</p><div class="button-row end"><button class="v2-btn" data-studio-act="paste-bank">Paste different JSON</button><button class="v2-btn primary" data-studio-act="confirm-bank-import">Import this bank</button></div>`)}catch(problem){if(error){error.textContent=problem.message;error.classList.remove('hidden-v2')}field?.focus()}}

function aiTemplateProfile(){return{title:'Untitled SBA bank',audience:'Define the learner level',scope:'Define the topics, curriculum or source material',questionCount:20,difficultyMix:{Easy:20,Moderate:60,Hard:20},learningObjectives:[],sourceInstructions:'Use the supplied material where provided and identify any statement that requires current guideline verification.'}}
templateData=function(){return{schemaVersion:2,purpose:'Create an import-compatible question bank for BM4 SBA Studio',bankProfile:aiTemplateProfile(),instructions:['Return valid JSON only; do not wrap it in Markdown.','Create exactly five plausible, same-category options and one unambiguously best answer per question.','Use a zero-based answer index from 0 to 4.','Prefer application, discrimination, interpretation and integration over isolated trivia.','Avoid grammatical clues, answer-length clues, repeated stems and implausible filler options.','Provide a specific why-correct explanation and a distinct explanation for every distractor.','For every question, include deepReview with two to four decisive phrases copied verbatim from the final stem.','Each key clue must explain what the quoted phrase contributes, list supported answer indexes and list answer indexes it argues against.','Never place HTML or styling in JSON. The site controls yellow, green and red presentation.','Include a concise key concept, common traps, recognition points and up to three follow-up questions.','Do not invent sources. Put dose, threshold, guideline or management claims in sourceNotes with a source and review date where available.','Before returning JSON, verify every clue quote exists exactly in the final stem and that the correct answer is never listed under arguesAgainst.','Metadata labels are user-defined. Use specific, consistent module, theme, subject, topic, objective and difficulty values instead of padding categories.'],requiredTopLevel:['schemaVersion','setId','title','questions'],questionSchema:{id:'unique string or integer',stem:'string',options:['five option strings'],answer:'integer 0–4',why:'why the best answer is correct',distractors:['five strings; the correct-answer position may be empty'],module:'optional course or block label',theme:'optional broad category',subjects:['optional overlapping labels'],topic:'specific concept',lo:['optional learning objectives'],domain:'optional question type',difficulty:'Easy | Moderate | Hard',image:{optional:true,src:'direct HTTPS or supported data image URL',alt:'descriptive text',caption:'neutral caption',credit:'source and licence'},deepReview:{version:1,testedConcept:'string',keyClues:[{id:'stable clue id',quote:'verbatim phrase from stem',occurrence:1,explanation:['one or more teaching points'],supports:[0],arguesAgainst:[1,2]}],keyConcept:{summary:'concise summary',paragraphs:['teaching paragraphs'],comparisonPoints:[{label:'concept or option',text:'contrast'}]},commonTraps:['specific misconception'],recogniseNextTime:['transferable recognition point'],followUpQuestions:[{prompt:'retrieval question',answer:'answer'}],sourceNotes:['optional source and review date']}},qualityChecks:['Every clue quote is verbatim','Every option index is valid','Correct answer is not marked negative','No repeated distractor boilerplate','No unsupported guideline claims','No raw HTML'],example:{schemaVersion:2,setId:'example-cardiology',title:'Example Cardiology Bank',questions:[{id:'cardio-001',stem:'A patient develops complete heart block after an inferior myocardial infarction. Which artery is most likely to be affected?',options:['Right coronary artery','Left anterior descending artery','Circumflex artery','Left main stem','Coronary sinus'],answer:0,why:'The AV nodal artery most often arises from the right coronary artery.',distractors:['','The LAD mainly supplies the anterior septum and bundle branches.','The circumflex supplies the AV node in a minority with left-dominant circulation.','The left main stem divides into LAD and circumflex and is not the usual direct AV nodal supply.','The coronary sinus is a venous structure.'],module:'Cardiovascular medicine',theme:'Cardiology',subjects:['Anatomy','Clinical'],topic:'AV nodal blood supply',lo:['Relate coronary anatomy to conduction abnormalities'],domain:'Applied anatomy',difficulty:'Moderate',deepReview:{version:1,testedConcept:'AV nodal blood supply',keyClues:[{id:'heart-block',quote:'complete heart block',occurrence:1,explanation:['This localises the problem to the AV conduction system.'],supports:[0],arguesAgainst:[]},{id:'inferior-mi',quote:'inferior myocardial infarction',occurrence:1,explanation:['Inferior territory is most commonly supplied by the right coronary artery.'],supports:[0],arguesAgainst:[1,3]}],keyConcept:{summary:'The AV node is supplied by the RCA in most people.',paragraphs:['AV nodal ischaemia is especially associated with inferior myocardial infarction.'],comparisonPoints:[{label:'LAD',text:'More strongly associated with anterior septal and bundle branch injury.'}]},commonTraps:['Confusing AV nodal block with bundle branch block.'],recogniseNextTime:['Inferior infarction plus AV block points toward the RCA.'],followUpQuestions:[{prompt:'Which conduction abnormality commonly occurs in inferior MI?',answer:'AV nodal block, often Mobitz I.'}],sourceNotes:[]}}]}}};
const baseTaxonomyTemplateData=templateData;
templateData=function(){const template=baseTaxonomyTemplateData();template.taxonomyVersion=TAXONOMY_VERSION;template.taxonomy=taxonomySchema();template.instructions=template.instructions.map(line=>line.startsWith('Metadata labels are user-defined.')?'Use the exact canonical theme, subject, domain and difficulty labels supplied in taxonomy. Module, topic and learning objectives remain specific to the curriculum.':line);template.instructions.push('Do not invent category variants such as cardiac or cardiology; use Cardiovascular exactly.');template.requiredTopLevel=['schemaVersion','taxonomyVersion','taxonomy','setId','title','questions'];template.questionSchema.theme='exactly one value from taxonomy.themes';template.questionSchema.subjects=['one or more exact values from taxonomy.subjects'];template.questionSchema.domain='exactly one value from taxonomy.domains';template.questionSchema.difficulty='exactly one value from taxonomy.difficulties';template.qualityChecks.push('Every reporting category matches the canonical taxonomy exactly');template.example.taxonomyVersion=TAXONOMY_VERSION;template.example.taxonomy=taxonomySchema();template.example.questions.forEach(canonicaliseQuestionTaxonomy);return template};

function aiSetId(title){return String(title||'sba-bank').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)||'sba-bank'}
function aiOutputSkeleton(profile={}){return{schemaVersion:2,taxonomyVersion:TAXONOMY_VERSION,taxonomy:taxonomySchema(),setId:aiSetId(profile.title),title:profile.title||'REPLACE_WITH_BANK_TITLE',questions:[{id:'REPLACE_WITH_UNIQUE_QUESTION_ID',stem:'REPLACE_WITH_COMPLETE_QUESTION_STEM',options:['REPLACE_WITH_OPTION_A','REPLACE_WITH_OPTION_B','REPLACE_WITH_OPTION_C','REPLACE_WITH_OPTION_D','REPLACE_WITH_OPTION_E'],answer:0,why:'REPLACE_WITH_WHY_THE_BEST_ANSWER_IS_CORRECT',distractors:['REPLACE_WITH_OPTION_A_FEEDBACK','REPLACE_WITH_OPTION_B_FEEDBACK','REPLACE_WITH_OPTION_C_FEEDBACK','REPLACE_WITH_OPTION_D_FEEDBACK','REPLACE_WITH_OPTION_E_FEEDBACK'],module:'REPLACE_WITH_CURRICULUM_MODULE',theme:'REPLACE_WITH_EXACT_TAXONOMY_THEME',subjects:['REPLACE_WITH_EXACT_TAXONOMY_SUBJECT'],topic:'REPLACE_WITH_SPECIFIC_TOPIC',lo:['REPLACE_WITH_LEARNING_OBJECTIVE'],domain:'REPLACE_WITH_EXACT_TAXONOMY_DOMAIN',difficulty:'REPLACE_WITH_EXACT_TAXONOMY_DIFFICULTY',deepReview:{version:1,testedConcept:'REPLACE_WITH_TESTED_CONCEPT',keyClues:[{id:'REPLACE_WITH_STABLE_CLUE_ID',quote:'REPLACE_WITH_VERBATIM_PHRASE_FROM_STEM',occurrence:1,explanation:['REPLACE_WITH_WHAT_THIS_CLUE_CONTRIBUTES'],supports:[0],arguesAgainst:[1]}],keyConcept:{summary:'REPLACE_WITH_CONCISE_SUMMARY',paragraphs:['REPLACE_WITH_TEACHING_PARAGRAPH'],comparisonPoints:[{label:'REPLACE_WITH_CONCEPT_OR_OPTION',text:'REPLACE_WITH_USEFUL_CONTRAST'}]},commonTraps:['REPLACE_WITH_SPECIFIC_MISCONCEPTION'],recogniseNextTime:['REPLACE_WITH_TRANSFERABLE_RECOGNITION_POINT'],followUpQuestions:[{prompt:'REPLACE_WITH_RETRIEVAL_QUESTION',answer:'REPLACE_WITH_ANSWER'}],sourceNotes:[]}}]}}
const taxonomyPromptTemplateData=templateData;
templateData=function(){const template=taxonomyPromptTemplateData();template.task='POPULATE outputTemplate into the final import-ready question-bank JSON. Do not return this instruction pack and do not write questions as prose.';template.instructions.unshift('This is a JSON population task: replace every REPLACE_ placeholder, duplicate the example question object until bankProfile.questionCount is reached, and return only the populated outputTemplate object.');template.outputTemplate=aiOutputSkeleton(template.bankProfile);return template};

function aiBuilderModal(){modal(`<div class="q-top"><div><span class="eyebrow">Bring your own AI</span><h2>AI Bank Builder</h2></div><button class="v2-btn" data-act="close-modal">Close</button></div><p>Describe the bank you want. The workspace will create a provider-neutral prompt that tells ChatGPT, Claude, Gemini or another AI to populate an import-ready JSON template.</p><div class="form-grid"><label class="field"><span>Bank title</span><input id="aiTitle" value="Untitled SBA bank"></label><label class="field"><span>Learner level</span><input id="aiAudience" placeholder="e.g. medical students studying cardiovascular physiology"></label><label class="field field-wide"><span>Scope or topics</span><textarea id="aiScope" rows="4" placeholder="What should and should not be covered?"></textarea></label><label class="field"><span>Number of questions</span><input id="aiCount" type="number" min="1" max="500" value="20"></label><label class="field"><span>Difficulty mix</span><input id="aiDifficulty" value="20% Easy, 60% Moderate, 20% Hard"></label><label class="field field-wide"><span>Learning objectives or source instructions</span><textarea id="aiObjectives" rows="6" placeholder="Paste objectives, notes or instructions here. Do not paste confidential information into third-party AI services."></textarea></label></div><div class="insight"><b>The AI is given the actual JSON structure to complete.</b><br>It is explicitly told to replace every placeholder, create the requested number of question objects, include feedback and Deep Review, and return JSON only.</div><div class="button-row end"><button class="v2-btn" data-studio-act="save-ai-population-prompt">Save AI prompt</button><button class="v2-btn primary" data-studio-act="copy-ai-population-prompt">Copy JSON-population prompt</button></div>`)}
function aiBriefFromForm(){const template=templateData(),objectives=document.getElementById('aiObjectives').value.trim();template.bankProfile={title:document.getElementById('aiTitle').value.trim()||'Untitled SBA bank',audience:document.getElementById('aiAudience').value.trim()||'Define the learner level',scope:document.getElementById('aiScope').value.trim()||'Define the scope',questionCount:Math.max(1,Number(document.getElementById('aiCount').value)||20),difficultyMix:document.getElementById('aiDifficulty').value.trim(),learningObjectives:objectives?objectives.split(/\n+/).map(x=>x.trim()).filter(Boolean):[],sourceInstructions:'Use only material the user supplies when they request source-grounded generation. Flag clinical details that require current guideline verification.'};template.outputTemplate=aiOutputSkeleton(template.bankProfile);return template}
function aiPromptFromForm(){const brief=aiBriefFromForm();return`POPULATE AN IMPORT-READY SBA WORKSPACE JSON BANK\n\nThis is a JSON completion task, not a request for a prose list of questions. Populate the output template below and return the completed JSON object only. Do not return this instruction pack, commentary, Markdown fences or any text before or after the JSON.\n\nCreate exactly ${brief.bankProfile.questionCount} complete question objects. Duplicate the example object structure as needed, replace every value beginning with REPLACE_, keep exactly five options per question, and use a zero-based answer index from 0 to 4. The distractors array must contain five option-specific explanations in the same order as options. Use only the exact reporting labels supplied in taxonomy. Every keyClue.quote must appear verbatim in its final stem. Remove optional fields only when genuinely unused; never leave placeholders in the result.\n\nBANK REQUEST\n${JSON.stringify(brief.bankProfile,null,2)}\n\nAUTHORING AND QUALITY RULES\n${brief.instructions.map((rule,index)=>`${index+1}. ${rule}`).join('\n')}\n${brief.qualityChecks.map((rule,index)=>`Q${index+1}. ${rule}`).join('\n')}\n\nJSON TEMPLATE TO POPULATE\n${JSON.stringify(brief.outputTemplate,null,2)}`}
function downloadText(name,value){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([value],{type:'text/plain;charset=utf-8'}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

renderBanks=function(){header('Question bank manager');const banks=db.banks.filter(b=>!b.archived);document.getElementById('view').innerHTML=`<section class="result-card"><div class="q-top"><div><span class="eyebrow">Portable question banks</span><h1>Question banks</h1></div><button class="v2-btn" data-act="home">Home</button></div><p>Use the included collection or import a bank produced by any compatible AI. Every bank stays separate and can be exported again.</p><div class="bank-launch-row"><label class="v2-btn primary">Import JSON bank<input type="file" id="bankImport" accept=".json,application/json" hidden></label><button class="v2-btn" data-studio-act="ai-builder">AI Bank Builder</button><button class="v2-btn" data-act="ai-template">Download blank AI template</button><button class="v2-btn" data-act="export-bank">Export current bank</button></div><div class="import-guide"><b>AI workflow</b><span>1. Describe a bank</span><span>2. Copy the instruction pack</span><span>3. Generate JSON with your chosen AI</span><span>4. Import and validate here</span></div>${banks.map(b=>{const ds=countBy(b.data.questions,q=>[q.difficulty]),fq=feedbackAudit(b),da=deepAudit(b);return`<article class="bank-card ${b.id===db.currentBankId?'current':''}"><div class="q-top"><div><h2>${esc(b.title)} ${b.builtin?'<span class="tag">Included</span>':''}</h2><p class="muted">${b.data.questions.length} questions · Easy ${ds.Easy||0}, Moderate ${ds.Moderate||0}, Hard ${ds.Hard||0}</p><div class="bank-badges"><span class="tag">${da.authored} authored Deep Reviews</span><span class="tag">${da.fallback} feedback-derived</span>${fq.bad?`<span class="tag warning-tag">${fq.bad} feedback warnings</span>`:'<span class="tag good-tag">Feedback audit passed</span>'}</div></div><div class="button-row"><button class="v2-btn primary" data-bank-use="${b.id}" ${b.id===db.currentBankId?'disabled':''}>Use bank</button><button class="v2-btn" data-bank-rename="${b.id}">Rename</button>${b.builtin?'':`<button class="v2-btn danger" data-bank-delete="${b.id}">Delete</button>`}</div></div><details><summary>Coverage and categories</summary><p><b>Set ID:</b> ${esc(b.setId)}</p><p>${Object.entries(b.data.blueprint.actualTargets||{}).map(([k,v])=>`${esc(k)}: ${v}`).join(' · ')}</p></details></article>`}).join('')}</section>`;document.getElementById('bankImport').onchange=e=>importBankFile(e.target.files[0])};

let questionEditorState=null;
const editorTabs=[['question','Question & answers'],['feedback','Feedback'],['deep','Deep Review'],['details','Details & media'],['preview','Preview']];
function editorText(value){return esc(value).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/_([^_\n]+)_/g,'<em>$1</em>').replace(/`([^`\n]+)`/g,'<code>$1</code>').replace(/\n/g,'<br>')}
function editorLines(value){return String(value||'').split(/\n+/).map(x=>x.trim()).filter(Boolean)}
function editorBlocks(value){return String(value||'').split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean)}
function editorPairs(value){return editorLines(value).map(line=>{const at=line.indexOf('|');return at<0?null:[line.slice(0,at).trim(),line.slice(at+1).trim()]}).filter(x=>x&&x[0]&&x[1])}
function editorToolbar(target){return`<div class="format-toolbar" aria-label="Text formatting"><button type="button" data-studio-act="editor-format" data-target="${target}" data-format="bold"><b>B</b></button><button type="button" data-studio-act="editor-format" data-target="${target}" data-format="italic"><i>I</i></button><button type="button" data-studio-act="editor-format" data-target="${target}" data-format="code"><code>code</code></button><small>Line breaks are preserved. HTML is never accepted.</small></div>`}
function freshEditorQuestion(){const q={id:uid('q'),stem:'Untitled question',options:['Option A','Option B','Option C','Option D','Option E'],answer:0,why:'Explain why the best answer is correct.',distractors:['','Explain why option B is not the best answer.','Explain why option C is not the best answer.','Explain why option D is not the best answer.','Explain why option E is not the best answer.'],module:'Unspecified',theme:'General',subjects:['Clinical'],topic:'Unspecified',lo:['Add a learning objective'],domain:'Other',difficulty:'Moderate'};q.deepReview=fallbackDeepReview(q);return q}
function updateEditorBankStats(b){b.data.title=b.title;b.data.taxonomyVersion=TAXONOMY_VERSION;b.data.taxonomy=taxonomySchema();b.data.blueprint=b.data.blueprint||{};b.data.blueprint.total=b.data.questions.length;b.data.blueprint.actualTargets=countBy(b.data.questions,q=>[q.theme]);b.data.blueprint.actualSubjectTargets=countBy(b.data.questions,q=>q.subjects);b.data.blueprint.targets={...b.data.blueprint.actualTargets};b.data.blueprint.subjectTargets={...b.data.blueprint.actualSubjectTargets}}
function makeEditableBank(source){if(!source.builtin)return source;const raw=clone(source.data);raw.setId='edited-'+Date.now().toString(36);raw.title=source.title.replace(/\s+—\s+Original Bank$/,'')+' — Edited copy';const copy=normaliseBank(raw);db.banks.push(copy);db.currentBankId=copy.id;save();toast('Editable copy created');return copy}
function createBlankEditorBank(){const raw={schemaVersion:2,setId:'custom-'+Date.now().toString(36),title:'Untitled question bank',questions:[freshEditorQuestion()]},b=normaliseBank(raw);db.banks.push(b);db.currentBankId=b.id;save();openQuestionEditor(b.id,0)}
function openQuestionEditor(bankId,index=0){const b=makeEditableBank(bank(bankId));db.currentBankId=b.id;save();questionEditorState={bankId:b.id,index:Math.max(0,Math.min(index,b.data.questions.length-1)),tab:'question',query:'',dirty:false,draft:clone(b.data.questions[Math.max(0,Math.min(index,b.data.questions.length-1))])};header('Question editor');renderQuestionEditor()}
function editorBank(){return questionEditorState&&bank(questionEditorState.bankId)}
function editorDraft(){return questionEditorState?.draft}
function editorListHtml(){const b=editorBank(),query=questionEditorState.query.toLowerCase();return b.data.questions.map((q,index)=>({q,index})).filter(({q,index})=>!query||(`${index+1} ${q.stem} ${q.topic} ${q.theme}`).toLowerCase().includes(query)).map(({q,index})=>`<button class="editor-question-link ${index===questionEditorState.index?'active':''}" type="button" data-studio-act="editor-question" data-index="${index}"><span>${index+1}</span><b>${esc(q.stem||'Untitled question')}</b><small>${esc(q.topic||q.theme||'Uncategorised')}</small></button>`).join('')||'<p class="empty-state">No matching questions.</p>'}
function editorChecks(kind,selected=[]){return`<div class="editor-option-checks">${[...letters].map((letter,index)=>`<label><input type="checkbox" data-editor-${kind}="${index}" ${selected.includes(index)?'checked':''}>${letter}</label>`).join('')}</div>`}
function editorQuestionTab(q){return`<section class="editor-pane"><div class="editor-section-head"><div><span class="eyebrow">Question</span><h2>Stem and answer options</h2></div><span class="tag">Question ${questionEditorState.index+1}</span></div><label class="editor-field"><span>Question stem</span>${editorToolbar('qeStem')}<textarea id="qeStem" rows="8" placeholder="Write the clinical scenario and question here">${esc(q.stem)}</textarea></label><div class="editor-options"><div class="editor-options-head"><b>Answer options</b><small>Select the radio button beside the single best answer.</small></div>${q.options.map((option,index)=>`<label class="editor-option-row ${index===q.answer?'correct':''}"><input type="radio" name="qeAnswer" value="${index}" ${index===q.answer?'checked':''}><b>${letters[index]}</b><input id="qeOption${index}" value="${esc(option)}" aria-label="Option ${letters[index]}"></label>`).join('')}</div><div class="editor-tip"><b>Formatting:</b> use <code>**bold**</code>, <code>_italic_</code> or <code>`+'`code`'+`</code>. The preview shows exactly what learners will see.</div></section>`}
function editorFeedbackTab(q){return`<section class="editor-pane"><div class="editor-section-head"><div><span class="eyebrow">Feedback</span><h2>Explain every option</h2></div></div><label class="editor-field"><span>Why the best answer is correct</span>${editorToolbar('qeWhy')}<textarea id="qeWhy" rows="6">${esc(q.why)}</textarea></label><div class="editor-feedback-list">${q.options.map((option,index)=>`<label class="editor-field editor-feedback-row ${index===q.answer?'correct':''}"><span><b>${letters[index]}. ${esc(option)}</b>${index===q.answer?'<em>Best answer — the main explanation above is shown</em>':'<em>Explain specifically why this is not the best answer</em>'}</span><textarea id="qeDistractor${index}" rows="3" ${index===q.answer?'placeholder="Optional note for the correct option"':''}>${esc(q.distractors[index]||'')}</textarea></label>`).join('')}</div></section>`}
function editorDeepTab(q){const dr=q.deepReview||fallbackDeepReview(q),kc=dr.keyConcept||{};return`<section class="editor-pane"><div class="editor-section-head"><div><span class="eyebrow">Optional expanded teaching</span><h2>Deep Review</h2></div><button class="v2-btn" type="button" data-studio-act="editor-add-clue" ${dr.keyClues.length>=6?'disabled':''}>+ Add key clue</button></div><label class="editor-field"><span>Tested concept</span><input id="qeTestedConcept" value="${esc(dr.testedConcept||'')}"></label><div class="editor-clues">${dr.keyClues.map((clue,clueIndex)=>`<article class="editor-clue" data-clue-index="${clueIndex}"><div class="q-top"><b>Key clue ${clueIndex+1}</b><button class="v2-btn danger" type="button" data-studio-act="editor-remove-clue" data-index="${clueIndex}">Remove</button></div><label class="editor-field"><span>Exact phrase copied from the question stem</span><input data-clue-quote value="${esc(clue.quote)}" placeholder="e.g. complete heart block"></label><label class="editor-field"><span>What this phrase tells the learner</span><textarea data-clue-explanation rows="3">${esc((clue.explanation||[]).join('\n'))}</textarea></label><div class="editor-clue-links"><div><span>Supports these answers</span>${editorChecks('supports',clue.supports)}</div><div><span>Argues against these answers</span>${editorChecks('against',clue.arguesAgainst)}</div></div></article>`).join('')}</div><div class="editor-subsection"><h3>Key concept</h3><label class="editor-field"><span>One-line summary</span>${editorToolbar('qeKeySummary')}<textarea id="qeKeySummary" rows="3">${esc(kc.summary||q.why)}</textarea></label><label class="editor-field"><span>Teaching paragraphs <small>Separate paragraphs with a blank line</small></span><textarea id="qeKeyParagraphs" rows="7">${esc((kc.paragraphs||[]).join('\n\n'))}</textarea></label><label class="editor-field"><span>Comparisons <small>One per line: label | explanation</small></span><textarea id="qeComparisons" rows="5">${esc((kc.comparisonPoints||[]).map(x=>`${x.label} | ${x.text}`).join('\n'))}</textarea></label></div><div class="editor-two-col"><label class="editor-field"><span>Common traps <small>One per line</small></span><textarea id="qeTraps" rows="5">${esc((dr.commonTraps||[]).join('\n'))}</textarea></label><label class="editor-field"><span>Recognise next time <small>One per line</small></span><textarea id="qeRecognise" rows="5">${esc((dr.recogniseNextTime||[]).join('\n'))}</textarea></label><label class="editor-field"><span>Follow-up questions <small>question | answer</small></span><textarea id="qeFollowUps" rows="5">${esc((dr.followUpQuestions||[]).map(x=>`${x.prompt} | ${x.answer||''}`).join('\n'))}</textarea></label><label class="editor-field"><span>Sources and review notes <small>One per line</small></span><textarea id="qeSources" rows="5">${esc((dr.sourceNotes||[]).join('\n'))}</textarea></label></div></section>`}
function taxonomyOptions(kind,selected){return STANDARD_TAXONOMY[kind].map(value=>`<option value="${esc(value)}" ${value===selected?'selected':''}>${esc(value)}</option>`).join('')}
function subjectTaxonomyPicker(selected=[]){const chosen=new Set(selected);return`<details class="taxonomy-picker"><summary>${chosen.size} selected · choose subjects</summary><div class="taxonomy-picker-menu">${STANDARD_TAXONOMY.subjects.map(value=>`<label><input type="checkbox" data-taxonomy-subject value="${esc(value)}" ${chosen.has(value)?'checked':''}><span>${esc(value)}</span></label>`).join('')}</div></details>`}
function editorDetailsTab(q){const image=q.image||{};return`<section class="editor-pane"><div class="editor-section-head"><div><span class="eyebrow">Organisation</span><h2>Details and media</h2></div><span class="tag">Canonical taxonomy v${TAXONOMY_VERSION}</span></div><div class="editor-tip taxonomy-tip"><b>Consistent reports:</b> themes, subjects, domains and difficulty use one shared set of labels. Module, topic and learning objectives remain flexible.</div><div class="editor-two-col"><label class="editor-field"><span>Module or collection <small>Custom label</small></span><input id="qeModule" value="${esc(q.module)}"></label><label class="editor-field"><span>Theme <small>Used in progress reports</small></span><select id="qeTheme">${taxonomyOptions('themes',q.theme)}</select></label><label class="editor-field"><span>Topic <small>Custom label</small></span><input id="qeTopic" value="${esc(q.topic)}"></label><label class="editor-field"><span>Domain or question type <small>Used in reports</small></span><select id="qeDomain">${taxonomyOptions('domains',q.domain)}</select></label><label class="editor-field"><span>Difficulty</span><select id="qeDifficulty">${taxonomyOptions('difficulties',q.difficulty)}</select></label><div class="editor-field"><span>Subjects <small>Choose one or more</small></span>${subjectTaxonomyPicker(q.subjects)}</div></div><label class="editor-field"><span>Learning objectives <small>One per line · custom labels</small></span><textarea id="qeLO" rows="4">${esc((q.lo||[]).join('\n'))}</textarea></label><div class="editor-subsection"><h3>Optional question image</h3><label class="editor-field"><span>Direct HTTPS or embedded data-image URL</span><input id="qeImageSrc" value="${esc(image.src||'')}" placeholder="https://…"></label><div class="editor-two-col"><label class="editor-field"><span>Accessible description</span><input id="qeImageAlt" value="${esc(image.alt||'')}"></label><label class="editor-field"><span>Visible caption</span><input id="qeImageCaption" value="${esc(image.caption||'')}"></label><label class="editor-field"><span>Credit or licence</span><input id="qeImageCredit" value="${esc(image.credit||'')}"></label></div></div></section>`}
function editorPreviewTab(q){
  const dr=q.deepReview||fallbackDeepReview(q),kc=dr.keyConcept||{},validClues=(dr.keyClues||[]).filter(c=>c.quote&&occurrenceExists(q.stem,c.quote,c.occurrence||1));
  const pointers=clue=>`${clue.supports?.length?`<div class="pointer-row"><small>Supports</small>${clue.supports.map(index=>`<span class="answer-pointer positive">${letters[index]}. ${editorText(q.options[index])}</span>`).join('')}</div>`:''}${clue.arguesAgainst?.length?`<div class="pointer-row"><small>Argues against</small>${clue.arguesAgainst.map(index=>`<span class="answer-pointer negative">${letters[index]}. ${editorText(q.options[index])}</span>`).join('')}</div>`:''}`;
  const deep=`<div class="editor-preview-deep"><span class="deep-section-label">Deep Review preview</span><h3>${editorText(dr.testedConcept||q.topic)}</h3><p class="concept-summary">${editorText(kc.summary||q.why)}</p>${validClues.length?`<section><span class="deep-section-label">Key clues</span>${validClues.map(clue=>`<div class="deep-clue"><mark class="clue-quote">${esc(clue.quote)}</mark>${(clue.explanation||[]).map(x=>`<p>${editorText(x)}</p>`).join('')}${pointers(clue)}</div>`).join('')}</section>`:'<p class="muted">No clue highlights added. The rest of the Deep Review will still be shown.</p>'}${(kc.paragraphs||[]).map(x=>`<p>${editorText(x)}</p>`).join('')}${kc.comparisonPoints?.length?`<ul class="comparison-list">${kc.comparisonPoints.map(x=>`<li><b>${editorText(x.label)}:</b> ${editorText(x.text)}</li>`).join('')}</ul>`:''}${dr.commonTraps?.length?`<section><span class="deep-section-label">Common traps</span><ul>${dr.commonTraps.map(x=>`<li>${editorText(x)}</li>`).join('')}</ul></section>`:''}${dr.recogniseNextTime?.length?`<section><span class="deep-section-label">Recognise it next time</span><ul>${dr.recogniseNextTime.map(x=>`<li>${editorText(x)}</li>`).join('')}</ul></section>`:''}${dr.followUpQuestions?.length?`<section><span class="deep-section-label">Test yourself</span>${dr.followUpQuestions.map(x=>`<details class="follow-up"><summary>${editorText(x.prompt)}</summary><p>${editorText(x.answer||'')}</p></details>`).join('')}</section>`:''}${dr.sourceNotes?.length?`<section class="source-notes"><span class="deep-section-label">Sources and review notes</span><ul>${dr.sourceNotes.map(x=>`<li>${editorText(x)}</li>`).join('')}</ul></section>`:''}</div>`;
  return`<section class="editor-pane"><div class="editor-section-head"><div><span class="eyebrow">Learner view</span><h2>Question preview</h2></div><span class="tag">${esc(q.difficulty)}</span></div><article class="editor-preview"><div class="question-stem">${validClues.length?highlightedStem(q.stem,validClues):editorText(q.stem)}</div>${safeImage(q)}<div class="editor-preview-options">${q.options.map((option,index)=>`<div class="review-option ${index===q.answer?'correct':''}"><b>${letters[index]}.</b> ${editorText(option)}${index===q.answer?' <span class="tag good-tag">Best answer</span>':''}</div>`).join('')}</div><h3>Why it is correct</h3><p>${editorText(q.why)}</p>${deep}</article></section>`
}
function editorPaneHtml(q){if(questionEditorState.tab==='question')return editorQuestionTab(q);if(questionEditorState.tab==='feedback')return editorFeedbackTab(q);if(questionEditorState.tab==='deep')return editorDeepTab(q);if(questionEditorState.tab==='details')return editorDetailsTab(q);return editorPreviewTab(q)}
function renderQuestionEditor(){const b=editorBank(),q=editorDraft();if(!b||!q)return renderBanks();document.getElementById('view').innerHTML=`<section class="question-editor"><header class="editor-header"><div><span class="eyebrow">Editing ${esc(b.title)}</span><h1>Question editor</h1><p class="muted">Save your edits here, then use <b>Save online</b> from Question banks to update the private account copy. Existing attempts keep their original question snapshots.</p></div><div class="button-row"><button class="v2-btn" type="button" data-studio-act="editor-back">← Banks</button><button class="v2-btn" type="button" data-act="export-bank">Export bank</button><button class="v2-btn primary" type="button" data-studio-act="editor-save">Save question</button></div></header><div class="editor-layout"><aside class="editor-sidebar"><div class="editor-sidebar-head"><label><span class="sr-only">Search questions</span><input id="qeSearch" class="search-input" value="${esc(questionEditorState.query)}" placeholder="Search questions…"></label><button class="v2-btn primary" type="button" data-studio-act="editor-add-question">+ New</button></div><div class="editor-question-list" id="editorQuestionList">${editorListHtml()}</div></aside><main class="editor-workspace"><nav class="editor-tabs" aria-label="Question editor sections">${editorTabs.map(([id,label])=>`<button type="button" class="editor-tab ${questionEditorState.tab===id?'active':''}" data-studio-act="editor-tab" data-tab="${id}">${label}</button>`).join('')}</nav>${editorPaneHtml(q)}<footer class="editor-actions"><div class="button-row"><button class="v2-btn" type="button" data-studio-act="editor-duplicate">Duplicate</button><button class="v2-btn" type="button" data-studio-act="editor-move" data-direction="-1" ${questionEditorState.index===0?'disabled':''}>Move up</button><button class="v2-btn" type="button" data-studio-act="editor-move" data-direction="1" ${questionEditorState.index===b.data.questions.length-1?'disabled':''}>Move down</button><button class="v2-btn danger" type="button" data-studio-act="editor-delete" ${b.data.questions.length===1?'disabled':''}>Delete</button></div><div class="button-row"><span class="editor-save-state">${questionEditorState.dirty?'Unsaved changes':'Saved'}</span><button class="v2-btn primary" type="button" data-studio-act="editor-save-next">Save & next →</button></div></footer></main></div></section>`}
function captureEditorTab(){const q=editorDraft();if(!q)return;const value=id=>document.getElementById(id)?.value;if(document.getElementById('qeStem')){q.stem=value('qeStem');q.options=q.options.map((_,i)=>value('qeOption'+i));q.answer=Number(document.querySelector('input[name="qeAnswer"]:checked')?.value||0)}if(document.getElementById('qeWhy')){q.why=value('qeWhy');q.distractors=q.options.map((_,i)=>value('qeDistractor'+i)||'')}if(document.getElementById('qeTestedConcept')){const old=q.deepReview||fallbackDeepReview(q),clues=[...document.querySelectorAll('.editor-clue')].map((node,index)=>({id:old.keyClues?.[index]?.id||`clue-${index+1}`,quote:node.querySelector('[data-clue-quote]').value.trim(),occurrence:1,explanation:editorLines(node.querySelector('[data-clue-explanation]').value),supports:[...node.querySelectorAll('[data-editor-supports]:checked')].map(x=>Number(x.dataset.editorSupports)),arguesAgainst:[...node.querySelectorAll('[data-editor-against]:checked')].map(x=>Number(x.dataset.editorAgainst))})).filter(x=>x.quote);q.deepReview={...old,version:1,generatedFallback:false,testedConcept:value('qeTestedConcept').trim(),keyClues:clues,keyConcept:{summary:value('qeKeySummary').trim(),paragraphs:editorBlocks(value('qeKeyParagraphs')),comparisonPoints:editorPairs(value('qeComparisons')).map(([label,text])=>({label,text}))},commonTraps:editorLines(value('qeTraps')),recogniseNextTime:editorLines(value('qeRecognise')),followUpQuestions:editorPairs(value('qeFollowUps')).map(([prompt,answer])=>({prompt,answer})),sourceNotes:editorLines(value('qeSources'))}}if(document.getElementById('qeModule')){q.module=value('qeModule').trim();q.theme=value('qeTheme');q.topic=value('qeTopic').trim();q.domain=value('qeDomain');q.difficulty=value('qeDifficulty');q.subjects=[...document.querySelectorAll('[data-taxonomy-subject]:checked')].map(x=>x.value);q.lo=editorLines(value('qeLO'));canonicaliseQuestionTaxonomy(q);const src=value('qeImageSrc').trim();if(src)q.image={src,alt:value('qeImageAlt').trim(),caption:value('qeImageCaption').trim(),credit:value('qeImageCredit').trim()};else delete q.image}}
function validateEditorQuestion(q){if(!q.stem.trim())throw Error('Add a question stem.');if(q.options.length!==5||q.options.some(x=>!String(x).trim()))throw Error('All five answer options need text.');if(!Number.isInteger(q.answer)||q.answer<0||q.answer>4)throw Error('Choose the single best answer.');if(!q.why.trim())throw Error('Explain why the best answer is correct.');for(let i=0;i<5;i++)if(i!==q.answer&&!String(q.distractors[i]||'').trim())throw Error(`Add specific feedback for option ${letters[i]}.`);for(const clue of q.deepReview?.keyClues||[]){if(!occurrenceExists(q.stem,clue.quote,clue.occurrence||1))throw Error(`The clue “${clue.quote}” must be copied exactly from the stem.`);if(clue.arguesAgainst.includes(q.answer))throw Error(`The correct answer cannot be marked against by the clue “${clue.quote}”.`)}return true}
function saveEditorQuestion(){captureEditorTab();const b=editorBank(),q=editorDraft();try{validateEditorQuestion(q);canonicaliseQuestionTaxonomy(q);normaliseDeepReview(q);b.data.questions[questionEditorState.index]=clone(q);updateEditorBankStats(b);save();questionEditorState.dirty=false;toast('Question saved');return true}catch(error){alert('Question not saved: '+error.message);return false}}
function discardEditorDraft(index){const b=editorBank();questionEditorState.index=index;questionEditorState.tab='question';questionEditorState.dirty=false;questionEditorState.draft=clone(b.data.questions[index]);renderQuestionEditor()}
function editorFormat(action){const input=document.getElementById(action.dataset.target);if(!input)return;const wrappers={bold:['**','**'],italic:['_','_'],code:['`','`']}[action.dataset.format]||['',''],start=input.selectionStart,end=input.selectionEnd,chosen=input.value.slice(start,end)||'text';input.setRangeText(wrappers[0]+chosen+wrappers[1],start,end,'select');input.focus();questionEditorState.dirty=true}

const basePublicRenderBanks=renderBanks;
renderBanks=function(){questionEditorState=null;basePublicRenderBanks();const launch=document.querySelector('.bank-launch-row');if(launch){const button=document.createElement('button');button.className='v2-btn';button.type='button';button.dataset.studioAct='editor-new-bank';button.textContent='+ New blank bank';launch.prepend(button);const paste=document.createElement('button');paste.className='v2-btn primary';paste.type='button';paste.dataset.studioAct='paste-bank';paste.textContent='Paste JSON';const fileImport=launch.querySelector('label');fileImport?.after(paste)}document.querySelectorAll('.bank-card').forEach((card,index)=>{const b=db.banks.filter(x=>!x.archived)[index],row=card.querySelector('.button-row');if(!b||!row)return;const button=document.createElement('button');button.className='v2-btn';button.type='button';button.dataset.studioAct='editor-open';button.dataset.bankId=b.id;button.textContent=b.builtin?'Edit a copy':'Edit questions';row.insertBefore(button,row.children[1]||null)})};

renderHistory=function(){
  header('Completed attempt history');
  const rows=[...db.history].reverse();
  document.getElementById('view').innerHTML=`<section class="result-card"><div class="q-top"><div><span class="eyebrow">Progress</span><h1>Attempt History</h1><p class="muted">Open an attempt to review it, or remove records you no longer need.</p></div><div class="button-row"><button class="v2-btn danger" type="button" data-studio-act="delete-all-attempts" ${rows.length?'':'disabled'}>Delete all attempts</button><button class="v2-btn" data-act="home">Home</button></div></div>${rows.length?`<table class="history-table"><thead><tr><th>Date</th><th>Session</th><th class="optional">Question set</th><th>Score</th><th class="optional">C / I / U</th><th class="optional">Mode</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(a=>{const m=metrics(a);return`<tr data-id="${esc(a.id)}" data-act="open-attempt"><td>${date(a.submittedAt)}</td><td>${esc(a.title)}<br><small>${a.questions.length} questions</small></td><td class="optional">${esc(a.bankTitle)}</td><td><b>${m.score}%</b></td><td class="optional">${m.correct} / ${m.incorrect} / ${m.unanswered}</td><td class="optional">${a.timingKnown===false?'Timing not recorded':a.timed?'Timed':'Untimed'} · ${esc(a.mode)}</td><td class="history-actions"><button class="v2-btn danger" type="button" data-studio-act="delete-attempt" data-attempt-id="${esc(a.id)}" aria-label="Delete ${esc(a.title)} from ${date(a.submittedAt)}">Delete</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty-state">No completed attempts yet.</div>'}</section>`
};

function deleteHistoryAttempt(id){
  const attempt=db.history.find(x=>String(x.id)===String(id));
  if(!attempt||!confirm(`Delete “${attempt.title}” from ${date(attempt.submittedAt)}? This cannot be undone unless it is included in an exported backup.`))return;
  db.history=db.history.filter(x=>String(x.id)!==String(id));
  if(viewAttempt&&String(viewAttempt.id)===String(id))viewAttempt=null;
  save();renderHistory();toast('Attempt deleted');
}
function deleteAllHistoryAttempts(){
  const count=db.history.length;
  if(!count||!confirm(`Delete all ${count} completed attempt${count===1?'':'s'}? This cannot be undone unless they are included in an exported backup.`))return;
  db.history=[];viewAttempt=null;save();renderHistory();toast('Attempt history cleared');
}

toolsModal=function(){modal(`<div class="q-top"><div><span class="eyebrow">Portable data</span><h2>Data & AI tools</h2></div><button class="v2-btn" data-act="close-modal">Close</button></div><div class="mini-list"><div class="mini-row"><span><b>Question banks</b><br><small class="muted">Import, validate, select and export multiple banks</small></span><button class="v2-btn" data-act="banks">Manage banks</button></div><div class="mini-row"><span><b>AI Bank Builder</b><br><small class="muted">Create provider-neutral instructions with the complete question and feedback schema</small></span><button class="v2-btn primary" data-studio-act="ai-builder">Open builder</button></div><div class="mini-row"><span><b>Blank AI template</b><br><small class="muted">Download the schema, quality rules and example bank</small></span><button class="v2-btn" data-act="ai-template">Save JSON</button></div><div class="mini-row"><span><b>Export all data</b><br><small class="muted">Banks, history, active session and preferences</small></span><button class="v2-btn" data-act="backup">Save backup</button></div><div class="mini-row"><span><b>Restore backup</b><br><small class="muted">Validated before any browser data changes</small></span><label class="v2-btn">Choose backup<input id="restoreBackup" type="file" accept=".json,application/json" hidden></label></div></div><p class="privacy-note"><b>Online accounts:</b> private banks can follow you between devices once you save them online. Imports are validated before anything is added to your workspace.</p>`);document.getElementById('restoreBackup').onchange=e=>restoreBackup(e.target.files[0])};

customBuilder=function(){const banks=db.banks.filter(b=>!b.archived),b=bank(),q=b.data.questions,uniq=f=>[...new Set(q.flatMap(x=>Array.isArray(f(x))?f(x):[f(x)]).filter(Boolean))].sort();modal(`<div class="q-top"><div><span class="eyebrow">Flexible session</span><h2>Custom practice</h2></div><button class="v2-btn" data-act="close-modal">Close</button></div><div class="form-grid"><div class="field"><span>Question bank</span><select id="cpBank">${banks.map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="field"><span>Number of questions</span><select id="cpCount"><option>10</option><option>20</option><option>40</option><option value="${q.length}">All ${q.length}</option><option value="custom">Custom…</option></select><input id="cpCustomCount" type="number" min="1" max="${q.length}" value="25" class="hidden-v2"></div><div class="field"><span>Difficulty</span><select id="cpDiff"><option value="all">All</option><option>Easy</option><option>Moderate</option><option>Hard</option><option value="Moderate|Hard">Moderate + Hard</option></select></div><div class="field"><span>Timing</span><select id="cpTimed"><option value="no">Untimed</option><option value="yes">Timed</option></select><input id="cpMinutes" type="number" min="1" value="45" class="hidden-v2" placeholder="Minutes"></div><div class="field field-wide"><span>When should answers appear?</span><select id="cpFeedback"><option value="instant">Instantly after each answer</option><option value="end">All at the end — no spoilers during the session</option></select></div><div class="field"><span>Previous activity</span><label class="check"><input type="checkbox" id="cpIncorrect"> Previously incorrect only</label><label class="check"><input type="checkbox" id="cpFlagged"> Previously flagged only</label><label class="check"><input type="checkbox" id="cpWeak"> Weak categories (n≥3, &lt;60%)</label><label class="check"><input type="checkbox" id="cpUnseen"> Unseen where possible</label></div><div class="field"><span>Themes (none = all)</span><div class="check-grid" id="cpThemes">${setOptions(uniq(x=>x.theme))}</div></div><div class="field"><span>Subjects (none = all)</span><div class="check-grid" id="cpSubjects">${setOptions(uniq(x=>x.subjects))}</div></div><div class="field"><span>Modules or collections (none = all)</span><div class="check-grid" id="cpModules">${setOptions(uniq(x=>x.module))}</div></div></div><div class="button-row end" style="margin-top:18px"><button class="v2-btn primary" data-act="build-practice">Build practice session</button></div>`);document.getElementById('cpCount').onchange=e=>document.getElementById('cpCustomCount').classList.toggle('hidden-v2',e.target.value!=='custom');document.getElementById('cpTimed').onchange=e=>document.getElementById('cpMinutes').classList.toggle('hidden-v2',e.target.value!=='yes');document.getElementById('cpBank').onchange=e=>{db.currentBankId=e.target.value;save();closeModal();customBuilder()}};
const baseCustomBuilderTiming=customBuilder;customBuilder=function(){baseCustomBuilderTiming();const select=document.getElementById('cpTimed'),field=select?.closest('.field');if(!field)return;field.innerHTML=`<span>Timing</span><div class="session-choice-grid timing-choice-grid"><label class="session-choice"><input type="radio" name="cpTimingChoice" value="no" checked><span><b>Untimed</b><small>Practise without a countdown.</small></span></label><label class="session-choice"><input type="radio" name="cpTimingChoice" value="yes"><span><b>Timed</b><small>Set a session duration.</small></span></label></div><input id="cpTimed" type="hidden" value="no"><input id="cpMinutes" type="number" min="1" value="45" class="hidden-v2" placeholder="Minutes">`;field.querySelectorAll('input[name="cpTimingChoice"]').forEach(radio=>radio.onchange=e=>{document.getElementById('cpTimed').value=e.target.value;document.getElementById('cpMinutes').classList.toggle('hidden-v2',e.target.value!=='yes')})};

function highlightedStem(stem,clues){const ranges=[];for(const clue of clues){let from=0,at=-1;for(let n=0;n<clue.occurrence;n++){at=stem.toLowerCase().indexOf(clue.quote.toLowerCase(),from);if(at<0)break;from=at+clue.quote.length}if(at>=0&&!ranges.some(r=>at<r.end&&at+clue.quote.length>r.start))ranges.push({start:at,end:at+clue.quote.length,id:clue.id})}ranges.sort((a,b)=>a.start-b.start);let out='',cursor=0;for(const range of ranges){out+=esc(stem.slice(cursor,range.start))+`<mark class="stem-clue" data-studio-act="focus-clue" data-clue-id="${esc(range.id)}" tabindex="0">${esc(stem.slice(range.start,range.end))}</mark>`;cursor=range.end}return out+esc(stem.slice(cursor))}
function optionChip(q,index,tone,order){const displayed=Math.max(0,order.indexOf(index));return`<span class="answer-pointer ${tone}">${letters[displayed]}. ${esc(q.options[index])}</span>`}
function deepReviewHtml(a,i){const q=a.questions[i],dr=q.deepReview||fallbackDeepReview(q),optionOrder=a.optionOrders[i]||q.options.map((_,j)=>j),o=outcome(a,i),seconds=a.times[i]||0,attempts=db.history.reduce((n,h)=>n+h.questions.filter(x=>finger(x)===finger(q)).length,0),confidence=a.confidence[i]||'Not rated',rating=db.prefs.deepReviewRatings?.[`${a.bankId}:${q.id}`];const clueHtml=dr.keyClues.map(clue=>`<article class="deep-clue" id="deep-clue-${esc(clue.id)}" data-studio-act="focus-stem" data-clue-id="${esc(clue.id)}"><button class="clue-quote" type="button">${esc(clue.quote)}</button>${clue.explanation.map(x=>`<p>${esc(x)}</p>`).join('')}${clue.supports.length?`<div class="pointer-row"><small>Supports</small>${clue.supports.map(x=>optionChip(q,x,'positive',optionOrder)).join('')}</div>`:''}${clue.arguesAgainst.length?`<div class="pointer-row"><small>Argues against</small>${clue.arguesAgainst.map(x=>optionChip(q,x,'negative',optionOrder)).join('')}</div>`:''}</article>`).join('');const kc=dr.keyConcept||{};return`<div class="deep-summary-row"><span class="deep-stat ${o}"><b>${o==='correct'?'Correct':o==='incorrect'?'Incorrect':'Unanswered'}</b><small>Result</small></span><span class="deep-stat"><b>${esc(confidence)}</b><small>Confidence</small></span><span class="deep-stat"><b>${fmtTime(seconds)}</b><small>${seconds<45?'Fast':seconds>(db.prefs.slowSeconds||120)?'Slow':'Steady'}</small></span><span class="deep-stat"><b>${attempts||1}</b><small>Times seen</small></span></div><button class="show-clues" data-studio-act="toggle-clues" type="button">Show key clues in the stem</button><section><span class="deep-section-label">Key clues</span>${clueHtml}</section><section class="key-concept-card"><span class="deep-section-label">Key concept</span><h3>${esc(dr.testedConcept)}</h3><p class="concept-summary">${esc(kc.summary||q.why)}</p>${(kc.paragraphs||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${kc.comparisonPoints?.length?`<ul class="comparison-list">${kc.comparisonPoints.map(x=>`<li><b>${esc(x.label)}:</b> ${esc(x.text)}</li>`).join('')}</ul>`:''}</section>${dr.commonTraps?.length?`<section><span class="deep-section-label">Common traps</span><ul>${dr.commonTraps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}${dr.recogniseNextTime?.length?`<section><span class="deep-section-label">Recognise it next time</span><ul>${dr.recogniseNextTime.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}${dr.followUpQuestions?.length?`<section><span class="deep-section-label">Test yourself</span>${dr.followUpQuestions.map(x=>`<details class="follow-up"><summary>${esc(x.prompt)}</summary><p>${esc(x.answer||'Use your own notes to check this point.')}</p></details>`).join('')}</section>`:''}${dr.sourceNotes?.length?`<section class="source-notes"><span class="deep-section-label">Sources and review notes</span><ul>${dr.sourceNotes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:''}<section class="ask-ai-card"><span class="deep-section-label">Continue with any AI</span><p>Copy a compact prompt containing this question, your answer and the bank's feedback.</p><button class="v2-btn" data-studio-act="copy-deep-prompt">Copy Ask AI prompt</button></section><div class="useful-row"><span>Was this useful?</span><button class="useful ${rating==='up'?'active':''}" data-studio-act="rate-deep" data-rating="up" aria-label="Useful">👍</button><button class="useful ${rating==='down'?'active':''}" data-studio-act="rate-deep" data-rating="down" aria-label="Not useful">👎</button></div>${dr.generatedFallback?'<p class="generated-note">This included-bank review was derived from its existing feedback. AI-generated imports can provide richer clue-specific teaching.</p>':''}`}
const baseDeepReviewHtml=deepReviewHtml;deepReviewHtml=function(a,i){let html=baseDeepReviewHtml(a,i).replace(/<div class="useful-row">[\s\S]*?<\/div>/,''),q=a.questions[i],dr=q.deepReview||fallbackDeepReview(q),values=[dr.keyConcept?.summary,...(dr.keyConcept?.paragraphs||[]),...(dr.keyClues||[]).flatMap(x=>x.explanation||[]),...(dr.commonTraps||[]),...(dr.recogniseNextTime||[])].filter(Boolean);for(const value of values){const plain=esc(value),formatted=editorText(value);if(plain!==formatted)html=html.replace(plain,formatted)}return html};
function openDeepReview(index,attempt=viewAttempt){if(!attempt)return;closeRanges();const panel=document.getElementById('deepReviewPanel'),q=attempt.questions[index];activeDeepReview={attempt,index};document.getElementById('deepReviewBody').innerHTML=deepReviewHtml(attempt,index);panel.setAttribute('aria-hidden','false');document.body.classList.add('deep-review-open');const stem=document.querySelector(`[data-q-stem="${index}"]`);if(stem){stem.innerHTML=highlightedStem(q.stem,q.deepReview.keyClues);stem.scrollIntoView({behavior:studioScrollBehavior(),block:'center'})}setTimeout(()=>panel.querySelector('[data-studio-act="close-deep-review"]')?.focus(),0)}
function closeDeepReview(){document.body.classList.remove('deep-review-open','deep-clues-hidden');document.getElementById('deepReviewPanel')?.setAttribute('aria-hidden','true');if(activeDeepReview){const stem=document.querySelector(`[data-q-stem="${activeDeepReview.index}"]`),q=activeDeepReview.attempt.questions[activeDeepReview.index];if(stem)stem.innerHTML=editorText(q.stem)}activeDeepReview=null}
function copyDeepPrompt(){if(!activeDeepReview)return;const{attempt:a,index:i}=activeDeepReview,q=a.questions[i],selected=a.answers[i];copyText(`Act as a concise medical SBA tutor. Explain the reasoning without inventing facts or sources.\n\nQUESTION\n${q.stem}\n\nOPTIONS\n${q.options.map((x,j)=>`${letters[j]}. ${x}`).join('\n')}\n\nMY ANSWER\n${selected===null?'Unanswered':q.options[selected]}\n\nCORRECT ANSWER\n${q.options[q.answer]}\n\nBANK FEEDBACK\n${q.why}\n\nPlease compare my answer with the correct answer, identify the decisive clues, explain the most likely misconception, and give one short transfer question.`)}

renderReview=function(a){const f=reviewFilter,slow=db.prefs.slowSeconds||120;f.visible=[];const html=a.questions.map((q,i)=>{const o=outcome(a,i),cc=confidenceClass(a,i),text=(q.module+' '+q.topic+' '+q.lo.join(' ')+' '+q.theme+' '+q.subjects.join(' ')).toLowerCase();let ok=f.outcome==='all'||f.outcome===o||f.outcome==='flagged'&&a.flags[i]||f.outcome==='misconception'&&cc==='misconception'||f.outcome==='slow'&&a.times[i]>slow||f.outcome==='slowCorrect'&&a.times[i]>slow&&o==='correct';if(f.category){const vals=f.category==='subject'?q.subjects:f.category==='lo'?q.lo:[q[f.category]];ok=ok&&vals.includes(f.value)}if(f.search&&!text.includes(f.search.toLowerCase()))ok=false;if(!ok)return'';f.visible.push(i);const order=a.optionOrders[i]||[0,1,2,3,4],coverage=q.deepReview?.generatedFallback?'Feedback-derived':'Authored';return`<article class="result-card review-item" id="review-${i}"><div class="q-top"><div><h2>Question ${i+1}</h2><span class="tag">${coverage} Deep Review</span></div><span class="result-label ${o}">${o.toUpperCase()}</span></div><p class="question-stem" data-q-stem="${i}">${esc(q.stem)}</p>${safeImage(q)}${order.map((canonical,pos)=>`<div class="review-option ${canonical===q.answer?'correct':''} ${canonical===a.answers[i]&&canonical!==q.answer?'chosen-wrong':''}"><b>${letters[pos]}.</b> ${esc(q.options[canonical])}${canonical===q.answer?' — Correct answer':''}${canonical===a.answers[i]?' — Your answer':''}${a.eliminated[i]?.[canonical]?' — Ruled out':''}</div>`).join('')}<p><b>Your answer:</b> ${a.answers[i]===null?'Unanswered':esc(q.options[a.answers[i]])}<br><b>Correct answer:</b> ${esc(q.options[q.answer])}<br><b>Confidence:</b> ${a.confidence[i]||'Not rated'} · <b>Active time:</b> ${fmtTime(a.times[i])} ${a.times[i]>slow?'· Slow':''}</p><div class="deep-review-launch"><div><b>Explore the reasoning</b><small>Highlight key clues, compare options and review the underlying concept.</small></div><button class="v2-btn primary" data-deep-review="${i}">Open Deep Review</button></div><h3>Why the correct answer is correct</h3><p>${esc(q.why)}</p><h3>Why the other options are wrong</h3>${distractorFeedback(q)}<div class="meta-line"><b>Module:</b> ${esc(q.module)} · <b>Topic:</b> ${esc(q.topic)} · <b>Learning objective:</b> ${esc(q.lo.join('; '))} · <b>Domain:</b> ${esc(q.domain)} · <b>Theme:</b> ${esc(q.theme)} · <b>Subjects:</b> ${esc(q.subjects.join(', '))} · <b>Difficulty:</b> ${esc(q.difficulty)}</div></article>`}).join('');document.getElementById('reviewList').innerHTML=html||'<div class="empty-state">No questions match this filter.</div>'};
const baseFormattedRenderReview=renderReview;renderReview=function(a){baseFormattedRenderReview(a);document.querySelectorAll('.review-item').forEach(item=>{const index=Number(item.id.replace('review-','')),q=a.questions[index],order=a.optionOrders[index]||[0,1,2,3,4],stem=item.querySelector('[data-q-stem]');if(stem)stem.innerHTML=editorText(q.stem);item.querySelectorAll('.review-option').forEach((node,pos)=>{const canonical=order[pos];node.innerHTML=`<b>${letters[pos]}.</b> ${editorText(q.options[canonical])}${canonical===q.answer?' — Correct answer':''}${canonical===a.answers[index]?' — Your answer':''}${a.eliminated[index]?.[canonical]?' — Ruled out':''}`});const heading=[...item.querySelectorAll('h3')].find(x=>x.textContent.includes('correct answer'));if(heading?.nextElementSibling)heading.nextElementSibling.innerHTML=editorText(q.why)})};

function helpModal(){modal(`<div class="q-top"><div><span class="eyebrow">Guide</span><h2>How BM4 SBA Studio works</h2></div><button class="v2-btn" data-act="close-modal">Close</button></div><div class="help-grid"><section><h3>Choose feedback timing</h3><p>Instant mode reveals correctness after each answer. End mode keeps all answers and explanations hidden until you submit.</p></section><section><h3>Review answers</h3><p>Every answer includes option-by-option feedback. Deep Review is available as an optional expanded explanation.</p></section><section><h3>Bring your own bank</h3><p>Use AI Bank Builder to create instructions for any AI. Import the returned JSON and review the validation preview before saving.</p></section><section><h3>Use your online workspace</h3><p>Sign in to keep private question banks with your account, update them from the bank manager, or publish selected banks to the Community Library.</p></section></div><div class="privacy-note"><b>Educational use:</b> imported medical content may be incomplete or outdated. Verify doses, thresholds and clinical pathways against current authoritative guidance.</div>`)}

document.addEventListener('click',async e=>{const deep=e.target.closest('[data-deep-review]'),live=e.target.closest('[data-live-deep-review]'),action=e.target.closest('[data-studio-act]');if(deep){e.preventDefault();e.stopPropagation();openDeepReview(Number(deep.dataset.deepReview));return}if(live){e.preventDefault();e.stopPropagation();if(db.current?.feedbackMode==='instant'&&db.current.answers[db.current.current]!==null)openDeepReview(Number(live.dataset.liveDeepReview),db.current);return}if(!action||action.dataset.studioAct?.startsWith('editor-'))return;const type=action.dataset.studioAct;if(type==='focus-clue'||type==='focus-stem'){e.preventDefault();e.stopPropagation();const id=action.dataset.clueId;if(type==='focus-clue'){document.getElementById('deep-clue-'+id)?.scrollIntoView({behavior:studioScrollBehavior(),block:'center'})}else{document.querySelector(`.stem-clue[data-clue-id="${CSS.escape(id)}"]`)?.scrollIntoView({behavior:studioScrollBehavior(),block:'center'})}return}e.preventDefault();e.stopPropagation();if(type==='close-deep-review')closeDeepReview();else if(type==='toggle-clues')document.body.classList.toggle('deep-clues-hidden');else if(type==='copy-deep-prompt')copyDeepPrompt();else if(type==='paste-bank')pasteBankModal();else if(type==='preview-pasted-bank')previewPastedBank();else if(type==='delete-attempt')deleteHistoryAttempt(action.dataset.attemptId);else if(type==='delete-all-attempts')deleteAllHistoryAttempts();else if(type==='rate-deep'&&activeDeepReview){const key=`${activeDeepReview.attempt.bankId}:${activeDeepReview.attempt.questions[activeDeepReview.index].id}`;db.prefs.deepReviewRatings=db.prefs.deepReviewRatings||{};db.prefs.deepReviewRatings[key]=action.dataset.rating;save();document.querySelectorAll('.useful').forEach(x=>x.classList.toggle('active',x===action))}else if(type==='help')helpModal();else if(type==='start-full-choice'){const feedbackMode=document.querySelector('input[name="fullFeedback"]:checked')?.value||'instant',timed=document.querySelector('input[name="fullTiming"]:checked')?.value==='yes';closeModalSafe();startFull(timed,feedbackMode)}else if(type==='custom-practice'){closeModalSafe();customBuilder()}else if(type==='ai-builder'){closeModalSafe();aiBuilderModal()}else if(type==='copy-ai-brief'){await copyText(JSON.stringify(aiBriefFromForm(),null,2));toast('AI instruction pack copied')}else if(type==='save-ai-brief'){download('BM4_AI_bank_instruction_pack.json',aiBriefFromForm())}else if(type==='confirm-bank-import'&&pendingBankImport){if(db.banks.some(x=>x.id===pendingBankImport.id))pendingBankImport.id=pendingBankImport.setId+'-'+Date.now();db.banks.push(pendingBankImport);db.currentBankId=pendingBankImport.id;pendingBankImport=null;save();closeModal();renderBanks();toast('Question bank imported')}} ,true);

document.addEventListener('click',async e=>{const action=e.target.closest('[data-studio-act="copy-ai-population-prompt"],[data-studio-act="save-ai-population-prompt"]');if(!action)return;e.preventDefault();e.stopPropagation();if(action.dataset.studioAct==='copy-ai-population-prompt'){await copyText(aiPromptFromForm());toast('JSON-population prompt copied')}else{downloadText('SBA_Workspace_AI_JSON_prompt.txt',aiPromptFromForm());toast('AI prompt saved')}},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-act="next"],[data-act="prev"],[data-act="jump"]')&&document.body.classList.contains('deep-review-open'))closeDeepReview();const action=e.target.closest('[data-studio-act^="editor-"]');if(!action)return;e.preventDefault();e.stopPropagation();const type=action.dataset.studioAct;if(type==='editor-new-bank')createBlankEditorBank();else if(type==='editor-open')openQuestionEditor(action.dataset.bankId);else if(type==='editor-back'){if(questionEditorState?.dirty&&!confirm('Discard unsaved changes to this question?'))return;questionEditorState=null;renderBanks()}else if(type==='editor-tab'){captureEditorTab();questionEditorState.tab=action.dataset.tab;renderQuestionEditor()}else if(type==='editor-question'){const index=Number(action.dataset.index);if(index===questionEditorState.index)return;if(questionEditorState.dirty&&!confirm('Discard unsaved changes to this question?'))return;discardEditorDraft(index)}else if(type==='editor-add-question'){if(questionEditorState.dirty&&!confirm('Discard unsaved changes and create a new question?'))return;const b=editorBank(),q=freshEditorQuestion();b.data.questions.push(q);updateEditorBankStats(b);save();discardEditorDraft(b.data.questions.length-1)}else if(type==='editor-save')saveEditorQuestion();else if(type==='editor-save-next'){if(saveEditorQuestion()){const next=Math.min(editorBank().data.questions.length-1,questionEditorState.index+1);discardEditorDraft(next)}}else if(type==='editor-duplicate'){if(questionEditorState.dirty&&!saveEditorQuestion())return;const b=editorBank(),copy=clone(b.data.questions[questionEditorState.index]);copy.id=uid('q');b.data.questions.splice(questionEditorState.index+1,0,copy);updateEditorBankStats(b);save();discardEditorDraft(questionEditorState.index+1);toast('Question duplicated')}else if(type==='editor-delete'){const b=editorBank();if(b.data.questions.length<=1||!confirm('Delete this question from the bank?'))return;b.data.questions.splice(questionEditorState.index,1);updateEditorBankStats(b);save();discardEditorDraft(Math.min(questionEditorState.index,b.data.questions.length-1));toast('Question deleted')}else if(type==='editor-move'){if(questionEditorState.dirty&&!saveEditorQuestion())return;const b=editorBank(),from=questionEditorState.index,to=from+Number(action.dataset.direction);if(to<0||to>=b.data.questions.length)return;[b.data.questions[from],b.data.questions[to]]=[b.data.questions[to],b.data.questions[from]];updateEditorBankStats(b);save();discardEditorDraft(to)}else if(type==='editor-add-clue'){captureEditorTab();const q=editorDraft(),dr=q.deepReview||fallbackDeepReview(q);dr.keyClues=dr.keyClues||[];if(dr.keyClues.length<6)dr.keyClues.push({id:uid('clue'),quote:deriveClueQuote(q),occurrence:1,explanation:['Explain what this exact phrase contributes to the reasoning.'],supports:[q.answer],arguesAgainst:[]});q.deepReview=dr;questionEditorState.dirty=true;renderQuestionEditor()}else if(type==='editor-remove-clue'){captureEditorTab();editorDraft().deepReview.keyClues.splice(Number(action.dataset.index),1);questionEditorState.dirty=true;renderQuestionEditor()}else if(type==='editor-format')editorFormat(action)},true);
document.addEventListener('input',e=>{if(!questionEditorState||!e.target.closest('.question-editor'))return;if(e.target.id==='qeSearch'){questionEditorState.query=e.target.value;const list=document.getElementById('editorQuestionList');if(list)list.innerHTML=editorListHtml();return}questionEditorState.dirty=true;const state=document.querySelector('.editor-save-state');if(state)state.textContent='Unsaved changes'},true);
document.addEventListener('change',e=>{if(questionEditorState&&e.target.closest('.question-editor')){questionEditorState.dirty=true;if(e.target.matches('[data-taxonomy-subject]')){const summary=e.target.closest('.taxonomy-picker')?.querySelector('summary'),count=document.querySelectorAll('[data-taxonomy-subject]:checked').length;if(summary)summary.textContent=`${count} selected · choose subjects`}const state=document.querySelector('.editor-save-state');if(state)state.textContent='Unsaved changes'}},true);
document.addEventListener('keydown',e=>{if(questionEditorState&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveEditorQuestion()}},true);
